// GetManyByIDs retrieves multiple Session records by their IDs in a single query
func (r *SessionRepository) GetManyByIDs(ctx context.Context, ids []types.IdentityUUID) (map[types.IdentityUUID]*types.Session, error) {
	if len(ids) == 0 {
		return map[types.IdentityUUID]*types.Session{}, nil
	}

	// Dedupe IDs
	seen := make(map[types.IdentityUUID]bool)
	uniqueIDs := make([]types.IdentityUUID, 0, len(ids))
	for _, id := range ids {
		if !seen[id] {
			seen[id] = true
			uniqueIDs = append(uniqueIDs, id)
		}
	}

	// Build WHERE id IN (...) clause
	placeholders := make([]string, len(uniqueIDs))
	args := make([]interface{}, len(uniqueIDs))
	for i, id := range uniqueIDs {
		placeholders[i] = fmt.Sprintf("$%d", i+1)
		args[i] = id.ToUUID()
	}

	// Build query with explicit column order
	query := fmt.Sprintf(`SELECT "id", "device", "agent", "presence_deadline", "presence_last_beat_at", "presence_missed", "presence_released", "status", "status_entered_at", "_version" FROM "session" WHERE id IN (%s)`, strings.Join(placeholders, ", "))

	// Execute query
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, args...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, args...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to execute query: %w", err)
	}
	defer rows.Close()

	// Scan results into map
	resultMap := make(map[types.IdentityUUID]*types.Session, len(uniqueIDs))
	for rows.Next() {
		entity := &types.Session{}

		// Create temporary variables for nullable fields that need pointer scanning

		var tempPresenceDeadline *types.TemporalDateTime
		var tempPresenceLastBeatAt *types.TemporalDateTime
		var tempPresenceMissed *bool
		var tempPresenceReleased []byte
		var tempStatusEnteredAt *types.TemporalDateTime

		// Create temporary variables for relationship foreign keys (we don't store these in the struct)

		// Scan all fields in schema order (matches DDL column order)
		err := rows.Scan(

			&entity.Id,

			&entity.Device,

			&entity.Agent,

			&tempPresenceDeadline,

			&tempPresenceLastBeatAt,

			&tempPresenceMissed,

			&tempPresenceReleased,

			&entity.Status,

			&tempStatusEnteredAt,

			&entity.Version,
		)
		if err != nil {
			return nil, fmt.Errorf("failed to scan row: %w", err)
		}

		// Copy nullable fields when present

		if tempPresenceDeadline != nil {
			entity.PresenceDeadline = tempPresenceDeadline
		}
		if tempPresenceLastBeatAt != nil {
			entity.PresenceLastBeatAt = tempPresenceLastBeatAt
		}
		if tempPresenceMissed != nil {
			entity.PresenceMissed = tempPresenceMissed
		}
		if len(tempPresenceReleased) > 0 {
			if err := unmarshalGenericJSONFieldValue(tempPresenceReleased, &entity.PresenceReleased); err != nil {
				return nil, fmt.Errorf("failed to decode JSON field presenceReleased: %w", err)
			}
		}
		if tempStatusEnteredAt != nil {
			entity.StatusEnteredAt = tempStatusEnteredAt
		}

		// Set relationship IDs from scanned FK values

		entityID, ok := sessionUUIDValue(entity.Id)
		if !ok {
			continue
		}
		resultMap[entityID] = entity
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating rows: %w", err)
	}

	return resultMap, nil
}

