// FindPage reads a page of the Session rows filter finds (D60, amended), in
// opts.Sort's order, ties broken by id in the same direction: up to
// opts.Limit rows after opts.After, and Next when more follow. It runs one
// query of opts.Limit + 1 rows and no count. A key is a row's id alone:
// in an order by a sort field, the query reads the key's row for its value,
// soft-deleted or not and whatever the filter, so a row the filter no longer
// finds still places the page. An After that holds no id, or whose row
// no longer exists in an order by a sort field, is ErrPageKey. A key of another
// order cannot be told from one of this order: the router refuses a cursor
// of another sort before FindPage reads it.
func (r *SessionRepository) FindPage(ctx context.Context, filter *SessionFilter, opts *SessionPageOptions) (*SessionPage, error) {
	if opts == nil || opts.Fields.IsZero() {
		return nil, fmt.Errorf("fields must be specified in PageOptions for performance")
	}
	if opts.Limit < 0 {
		return nil, fmt.Errorf("orm: a page of Session rows holds 1 or more, not %d", opts.Limit)
	}
	limit := opts.Limit
	if limit == 0 {
		limit = 100
	}
	field := opts.Sort.Field
	if field == "" {
		field = SessionSortById
	}
	column, ok := sessionSortColumns[field]
	if !ok {
		return nil, fmt.Errorf("orm: Session sorts by id, device, agent, presenceDeadline, presenceLastBeatAt, status and statusEnteredAt, not %q", string(field))
	}
	byKey := field == SessionSortById

	// Next is the key of the page's last row, so the page reads its primary
	// key whatever Fields selects.
	fieldStrings := sessionFieldStrings(opts.Fields)
	if !containsString(fieldStrings, "id") {
		fieldStrings = append(fieldStrings, "id")
	}
	if err := validateFields(fieldStrings, SessionAllowedFields); err != nil {
		return nil, err
	}
	selectFields := buildSelectFieldsTyped(fieldStrings, "session")
	// The filter's conditions, each qualified by the table, then the
	// keyset's.
	var args []interface{}
	conditions := filter.conditions(&args, 0)
	comparison, direction := ">", "ASC"
	if opts.Sort.Desc {
		comparison, direction = "<", "DESC"
	}
	var key any
	if opts.After != nil {
		var err error
		if key, err = opts.After.arg(); err != nil {
			return nil, err
		}
		args = append(args, key)
		placeholder := fmt.Sprintf("$%d", len(args))
		afterKey := fmt.Sprintf(`"session".id %s %s`, comparison, placeholder)
		if byKey {
			conditions = append(conditions, afterKey)
		} else {
			// The key's row gives the sort field's value: no deleted_at
			// condition and no filter, so a row soft-deleted or changed
			// since the page before still places this one.
			after := fmt.Sprintf(`(%s, "session".id) %s ((SELECT %s FROM "session" AS page_key WHERE page_key.id = %s), %s)`,
				column.sql, comparison, column.key, placeholder, placeholder)
			if column.nulls {
				// Nulls come last in either direction (D112): after a
				// null, the nulls past the key; after a value, every null
				// and the values past it.
				after = fmt.Sprintf(`CASE (SELECT %s IS NULL FROM "session" AS page_key WHERE page_key.id = %s) WHEN TRUE THEN %s IS NULL AND %s WHEN FALSE THEN (%s IS NULL OR %s) END`,
					column.key, placeholder, column.sql, afterKey, column.sql, after)
			}
			conditions = append(conditions, after)
		}
	}
	whereClause := ""
	if len(conditions) > 0 {
		whereClause = " WHERE " + strings.Join(conditions, " AND ")
	}
	orderByClause := fmt.Sprintf(" ORDER BY %s %s", column.sql, direction)
	if column.nulls {
		orderByClause = fmt.Sprintf(" ORDER BY %s %s NULLS LAST", column.sql, direction)
	}
	if !byKey {
		orderByClause += fmt.Sprintf(`, "session".id %s`, direction)
	}
	query := fmt.Sprintf(`SELECT %s FROM "session"%s%s LIMIT %d`, selectFields, whereClause, orderByClause, limit+1)

	rows, err := r.findRows(ctx, "FindPage", query, args, fieldStrings, opts.Fields)
	if err != nil {
		return nil, err
	}
	if len(rows) == 0 && opts.After != nil && !byKey {
		// A key whose row no longer exists places no row: its value is
		// null, which no row comes after. Only then is the page empty
		// without being the last.
		if err := r.pageKeyExists(ctx, key); err != nil {
			return nil, err
		}
	}
	page := &SessionPage{Rows: rows}
	if len(rows) > limit {
		page.Rows = rows[:limit]
		page.Next = sessionPageKeyOf(page.Rows[limit-1])
	}
	return page, nil
}

// pageKeyExists is nil when the table holds a row whose primary key is key,
// soft-deleted or not, and ErrPageKey when it holds none.
func (r *SessionRepository) pageKeyExists(ctx context.Context, key any) error {
	query := `SELECT EXISTS (SELECT 1 FROM "session" WHERE "session".id = $1)`
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, key)
	} else {
		row = r.db.pool.QueryRow(ctx, query, key)
	}
	var exists bool
	if err := row.Scan(&exists); err != nil {
		return fmt.Errorf("failed to read the page key's row: %w", err)
	}
	if !exists {
		return fmt.Errorf("%w: no Session row has the key's id", ErrPageKey)
	}
	return nil
}

// CreateOne inserts a new Session row through the behaviors' core (D103), in
// a transaction: each behavior's create initializes the fields it owns, and
// the row is read back. A refusal of the core's is returned as the
// *rules.Refusal it is.
func (r *SessionRepository) CreateOne(ctx context.Context, input *SessionCreate) (*types.Session, error) {
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Session, error) {
		return (&SessionRepository{tx: tx, txDB: r.database()}).createThroughCore(ctx, input)
	})
}

// sessionUniqueKeys are the conflict targets of Session's unique keys, and
// the assignment of the update an upsert that sets nothing names, which its
// WHERE FALSE never runs (sqlutil.UniqueKey, D79); the read of the rows
// that hold keys, which an upsert reads back when it leaves them as they
// were, empty for a key over an expression, and that key's read of the row
// that holds one input's value of it, empty for a key over columns; and the
// key's columns as a batch insert's cells name them (D89).
var sessionUniqueKeys = map[SessionUniqueKey]struct {
	conflict, keep, rows, held string
	columns                    []string
}{
	SessionUniqueById: {`(id)`, `id = "session".id`, `SELECT "id", "device", "agent", "presence_deadline", "presence_last_beat_at", "presence_missed", "presence_released", "status", "status_entered_at", "_version" FROM "session" WHERE (id) IN (%s)`, ``, []string{`id`}},
}

// sessionKeyOf is the text of row's values of the unique key on, as
// UpsertMany matches the rows a statement returns to its inputs, or false
// when the insert leaves one of them to the database (D89).
func sessionKeyOf(on SessionUniqueKey, row *types.Session) (string, bool) {
	switch on {
	case SessionUniqueById:
		return upsertKeyText(upsertKeyValue(row.Id, false))
	}
	return "", false
}

// database is the Database the repository runs on.
func (r *SessionRepository) database() *Database {
	if r.txDB != nil {
		return r.txDB
	}
	return r.db
}

// scanReturned scans a row of every column of Session, as a write returns
// it, and, with inserted, the flag an upsert returns after them (D89).
func (r *SessionRepository) scanReturned(row pgx.Row, inserted *bool) (*types.Session, error) {
	result := &types.Session{}
	// Create temporary variables for nullable fields that need pointer scanning

	var tempPresenceDeadline *types.TemporalDateTime
	var tempPresenceLastBeatAt *types.TemporalDateTime
	var tempPresenceMissed *bool
	var tempPresenceReleased []byte
	var tempStatusEnteredAt *types.TemporalDateTime

	// Create temporary variables for relationship foreign keys (we don't store these in the struct)

	// Scan all fields in schema order (matches DDL column order)
	dest := []any{

		&result.Id,

		&result.Device,

		&result.Agent,

		&tempPresenceDeadline,

		&tempPresenceLastBeatAt,

		&tempPresenceMissed,

		&tempPresenceReleased,

		&result.Status,

		&tempStatusEnteredAt,

		&result.Version,
	}
	if inserted != nil {
		dest = append(dest, inserted)
	}
	if err := row.Scan(dest...); err != nil {
		return nil, err
	}

	// Copy nullable fields when present

	if tempPresenceDeadline != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.PresenceDeadline = tempPresenceDeadline
	}
	if tempPresenceLastBeatAt != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.PresenceLastBeatAt = tempPresenceLastBeatAt
	}
	if tempPresenceMissed != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.PresenceMissed = tempPresenceMissed
	}
	if len(tempPresenceReleased) > 0 {
		if err := unmarshalGenericJSONFieldValue(tempPresenceReleased, &result.PresenceReleased); err != nil {
			return nil, fmt.Errorf("failed to decode JSON field presenceReleased: %w", err)
		}
	}
	if tempStatusEnteredAt != nil {
		// Nullable enum/scalar: typegen emits *Enum or *Scalar, assign pointer directly
		result.StatusEnteredAt = tempStatusEnteredAt
	}

	// Set relationship IDs from scanned FK values

	return result, nil
}

// upsertRow is UpsertOneResult on the repository's connection: the upsert,
// a read of the row it left as it was, when the update sets no field or
// only if changed, and the second statement of an encrypted field.
func (r *SessionRepository) upsertRow(ctx context.Context, input *types.Session, on SessionUniqueKey, update *SessionUpdate, onlyIfChanged bool) (*UpsertResult[*types.Session], error) {
	key := sessionUniqueKeys[on]
	// Set audit fields

	// Build INSERT query
	var fields []string
	var placeholders []string
	var values []interface{}
	paramNum := 0
	// Schema-owned identities may supply a stable UUID. A zero value keeps the
	// database-generated default used by ordinary creates.
	{
		var zeroPrimaryKey types.IdentityUUID
		if primaryKey, ok := sessionUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
			fields = append(fields, `id`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, primaryKey.ToUUID())
		}
	}
	// Required field: device
	fields = append(fields, `device`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Device.ToUUID())
	// Required field: agent
	fields = append(fields, `agent`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Agent)
	// Optional field: presenceDeadline - only add if set
	{
		if input.PresenceDeadline != nil {
			fields = append(fields, `presence_deadline`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.PresenceDeadline))
		}
	}
	// Optional field: presenceLastBeatAt - only add if set
	{
		if input.PresenceLastBeatAt != nil {
			fields = append(fields, `presence_last_beat_at`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.PresenceLastBeatAt))
		}
	}
	// Optional field: presenceMissed - only add if set
	{
		if input.PresenceMissed != nil {
			fields = append(fields, `presence_missed`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
			values = append(values, *input.PresenceMissed)
		}
	}
	// Optional field: presenceReleased - only add if set
	{
		if input.PresenceReleased != nil {
			fields = append(fields, `presence_released`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			jsonValuePresenceReleased, err := marshalJSONFieldValue(input.PresenceReleased)
			if err != nil {
				return nil, fmt.Errorf("failed to marshal JSON field presenceReleased: %w", err)
			}
			values = append(values, jsonValuePresenceReleased)
		}
	}
	// Required field: status
	fields = append(fields, `status`)
	paramNum++
	placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
	values = append(values, input.Status)
	// Optional field: statusEnteredAt - only add if set
	{
		if input.StatusEnteredAt != nil {
			fields = append(fields, `status_entered_at`)
			paramNum++
			placeholders = append(placeholders, fmt.Sprintf("$%d", paramNum))
			values = append(values, time.Time(*input.StatusEnteredAt))
		}
	}

	// Handle relationship foreign key columns

	// Build the update of the row the key conflicts with, its placeholders
	// numbered after the insert's
	var setClauses, compareCurrent, compareNext []string
	if update.Device != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`device = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `"session".device`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, (*update.Device).ToUUID())
	}
	if update.Agent != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`agent = $%d`, paramNum))
		compareCurrent = append(compareCurrent, `"session".agent`)
		compareNext = append(compareNext, fmt.Sprintf(`$%d`, paramNum))
		values = append(values, *update.Agent)
	}

	assigned := len(setClauses)
	if assigned == 0 {
		// An update that sets no field compares none, so its WHERE is FALSE:
		// it leaves the row as it is, its version, stamps and history all,
		// and reads it back below.
		setClauses = append(setClauses, key.keep)
	} else {
		// Set updated_at

		// Set updated_by

	}

	query := fmt.Sprintf(
		`INSERT INTO "session" (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "device", "agent", "presence_deadline", "presence_last_beat_at", "presence_missed", "presence_released", "status", "status_entered_at", "_version", (xmax = 0) AS _inserted`,
		strings.Join(fields, ", "),
		"("+strings.Join(placeholders, ", ")+")",
		key.conflict,
		strings.Join(setClauses, ", "),
		upsertWhere(``, compareCurrent, compareNext, onlyIfChanged || assigned == 0),
	)

	// Execute query
	var row pgx.Row
	if r.tx != nil {
		row = r.tx.QueryRow(ctx, query, values...)
	} else {
		row = r.db.pool.QueryRow(ctx, query, values...)
	}
	var inserted bool
	scanned, err := r.scanReturned(row, &inserted)
	var upserted *UpsertResult[*types.Session]
	switch {
	case err == nil:
		status := UpsertUnchanged
		if inserted {
			status = UpsertInserted
		} else if assigned > 0 {
			status = UpsertUpdated
		}
		upserted = &UpsertResult[*types.Session]{Row: scanned, Status: status}
	case err != pgx.ErrNoRows:
		return nil, fmt.Errorf("failed to scan result: %w", err)
	case !onlyIfChanged && assigned > 0:
		// The row the key conflicts with is soft-deleted.
		return nil, ErrNotFound
	default:
		// The row the key conflicts with, which the update sets no field of
		// or which already held the update's values, read back by its key:
		// a soft-deleted one is ErrNotFound.
		keyValues, ok := upsertCellValues(upsertCells(fields, values), key.columns)
		if !ok {
			return nil, fmt.Errorf("no Session row holds an unset %s: %w", string(on), ErrNotFound)
		}
		found, err := r.heldOfKey(ctx, on, keyValues, input)
		if err != nil {
			return nil, err
		}
		upserted = &UpsertResult[*types.Session]{Row: found, Status: UpsertUnchanged}
	}
	return upserted, nil
}

// upsertBatches is UpsertMany on the repository's connection, a batch at a
// time: each batch's statement, a read of the rows it left as they were,
// when update names no field or only if changed, and the second statement
// of each encrypted field.
func (r *SessionRepository) upsertBatches(ctx context.Context, inputs []*types.Session, on SessionUniqueKey, update SessionFields, batch int, onlyIfChanged bool) ([]UpsertResult[*types.Session], error) {
	key := sessionUniqueKeys[on]

	// Set audit fields

	// Each field update names takes the value the input would have
	// inserted, which an upsert only if changed compares with the row's.
	var setClauses, compareCurrent, compareNext []string
	if update.Device {
		setClauses = append(setClauses, `device = EXCLUDED.device`)
		compareCurrent = append(compareCurrent, `"session".device`)
		compareNext = append(compareNext, `EXCLUDED.device`)
	}
	if update.Agent {
		setClauses = append(setClauses, `agent = EXCLUDED.agent`)
		compareCurrent = append(compareCurrent, `"session".agent`)
		compareNext = append(compareNext, `EXCLUDED.agent`)
	}

	results := make([]UpsertResult[*types.Session], 0, len(inputs))
	for start := 0; start < len(inputs); start += batch {
		chunk := inputs[start:min(start+batch, len(inputs))]
		prepared := chunk

		// The batch's rows, as CreateMany writes them.
		rows := make([][]batchInsertCell, 0, len(prepared))
		for _, input := range prepared {
			var row []batchInsertCell
			// Primary key: id. Schema-owned identities may supply a stable
			// UUID, matching CreateOne; a row without one takes the generated default.
			{
				cell := batchInsertCell{column: `id`}
				var zeroPrimaryKey types.IdentityUUID
				if primaryKey, ok := sessionUUIDValue(input.Id); ok && primaryKey != zeroPrimaryKey {
					cell.value, cell.set = primaryKey.ToUUID(), true
				}
				row = append(row, cell)
			}
			// Required field: device
			{
				cell := batchInsertCell{column: `device`, set: true}
				cell.value = input.Device.ToUUID()
				row = append(row, cell)
			}
			// Required field: agent
			{
				cell := batchInsertCell{column: `agent`, set: true}
				cell.value = input.Agent
				row = append(row, cell)
			}
			// Optional field: presenceDeadline
			{
				cell := batchInsertCell{column: `presence_deadline`}
				if input.PresenceDeadline != nil {
					cell.value = time.Time(*input.PresenceDeadline)
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: presenceLastBeatAt
			{
				cell := batchInsertCell{column: `presence_last_beat_at`}
				if input.PresenceLastBeatAt != nil {
					cell.value = time.Time(*input.PresenceLastBeatAt)
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: presenceMissed
			{
				cell := batchInsertCell{column: `presence_missed`}
				if input.PresenceMissed != nil {
					// Dereference pointer for database value (nullable complex types, enums, and scalars are pointers)
					cell.value = *input.PresenceMissed
					cell.set = true
				}
				row = append(row, cell)
			}
			// Optional field: presenceReleased
			{
				cell := batchInsertCell{column: `presence_released`}
				if input.PresenceReleased != nil {
					jsonValue, err := marshalJSONFieldValue(input.PresenceReleased)
					if err != nil {
						return nil, fmt.Errorf("failed to marshal JSON field presenceReleased: %w", err)
					}
					cell.value = jsonValue
					cell.set = true
				}
				row = append(row, cell)
			}
			// Required field: status
			{
				cell := batchInsertCell{column: `status`, set: true}
				cell.value = input.Status
				row = append(row, cell)
			}
			// Optional field: statusEnteredAt
			{
				cell := batchInsertCell{column: `status_entered_at`}
				if input.StatusEnteredAt != nil {
					cell.value = time.Time(*input.StatusEnteredAt)
					cell.set = true
				}
				row = append(row, cell)
			}

			// Relationship foreign key columns, matching CreateOne
			rows = append(rows, row)
		}
		fieldNames, valuePlaceholders, values := buildBatchInsert(rows)
		assignments := append([]string(nil), setClauses...)
		if len(setClauses) == 0 {
			// An update that names no field compares none, so its WHERE is
			// FALSE: it leaves each row as it is, its version, stamps and
			// history all, and reads it back below.
			assignments = append(assignments, key.keep)
		} else {
		}
		query := fmt.Sprintf(
			`INSERT INTO "session" (%s) VALUES %s ON CONFLICT %s DO UPDATE SET %s%s RETURNING "id", "device", "agent", "presence_deadline", "presence_last_beat_at", "presence_missed", "presence_released", "status", "status_entered_at", "_version", (xmax = 0) AS _inserted`,
			strings.Join(fieldNames, ", "),
			strings.Join(valuePlaceholders, ", "),
			key.conflict,
			strings.Join(assignments, ", "),
			upsertWhere(``, compareCurrent, compareNext, onlyIfChanged || len(setClauses) == 0),
		)
		returned, inserted, err := r.upsertReturned(ctx, query, values)
		if err != nil {
			return nil, err
		}

		// A row is its input's by the key's values; an input that sets none
		// of them, whose key the database generates, takes the next row whose
		// key no input holds, as the rows come back in the inputs' order.
		keys := make([]string, len(prepared))
		set := make([]bool, len(prepared))
		for i, input := range prepared {
			keys[i], set[i] = sessionKeyOf(on, input)
		}
		matcher := newUpsertMatcher(keys, set)
		matched := make([]*UpsertResult[*types.Session], len(prepared))
		for n, row := range returned {
			text, ok := sessionKeyOf(on, row)
			i := matcher.take(text, ok)
			if i < 0 {
				return nil, fmt.Errorf("orm: UpsertMany of Session wrote a row whose %s no input holds", string(on))
			}
			status := UpsertUnchanged
			if inserted[n] {
				status = UpsertInserted
			} else if len(setClauses) > 0 {
				status = UpsertUpdated
			}
			matched[i] = &UpsertResult[*types.Session]{Row: row, Status: status}
		}

		// A row it did not return is one it left as it was, when update
		// names no field or only if changed, which it reads back by its key,
		// or a deleted one.
		var left []int
		for i := range matched {
			if matched[i] == nil {
				left = append(left, i)
			}
		}
		if len(left) > 0 {
			if !onlyIfChanged && len(setClauses) > 0 {
				return nil, fmt.Errorf("the Session row that holds the %s of input %d is deleted: %w", string(on), start+left[0], ErrNotFound)
			}
			keyValues := make([][]any, len(left))
			wanted := make([]*types.Session, len(left))
			for n, i := range left {
				cells, ok := upsertCellValues(rows[i], key.columns)
				if !ok {
					return nil, fmt.Errorf("no Session row holds an unset %s: %w", string(on), ErrNotFound)
				}
				keyValues[n], wanted[n] = cells, prepared[i]
			}
			found, err := r.rowsOfKeys(ctx, on, keyValues, wanted)
			if err != nil {
				return nil, err
			}
			for n, i := range left {
				matched[i] = &UpsertResult[*types.Session]{Row: found[n], Status: UpsertUnchanged}
			}
		}
		for _, result := range matched {
			results = append(results, *result)
		}
	}
	return results, nil
}

// upsertReturned runs an upsert's statement, query with values, and scans
// each row it returns and whether it inserted it.
func (r *SessionRepository) upsertReturned(ctx context.Context, query string, values []any) ([]*types.Session, []bool, error) {
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, nil, fmt.Errorf("failed to execute upsert: %w", err)
	}
	defer rows.Close()
	var returned []*types.Session
	var inserted []bool
	for rows.Next() {
		var flag bool
		row, err := r.scanReturned(rows, &flag)
		if err != nil {
			return nil, nil, fmt.Errorf("failed to scan result: %w", err)
		}
		returned = append(returned, row)
		inserted = append(inserted, flag)
	}
	if err := rows.Err(); err != nil {
		return nil, nil, fmt.Errorf("error iterating results: %w", err)
	}
	return returned, inserted, nil
}

// rowsOfKeys reads the rows that hold keys, each the values of the unique
// key on an input's insert binds, among the rows the key's index holds, in
// the inputs' order: the rows an upsert left as they were, as one whose
// update sets no field or one only if changed does (D89). A key no live
// row holds is ErrNotFound.
func (r *SessionRepository) rowsOfKeys(ctx context.Context, on SessionUniqueKey, keys [][]any, inputs []*types.Session) ([]*types.Session, error) {
	tuples, values := upsertKeyTuples(keys)
	query := fmt.Sprintf(sessionUniqueKeys[on].rows, strings.Join(tuples, ", "))
	var rows pgx.Rows
	var err error
	if r.tx != nil {
		rows, err = r.tx.Query(ctx, query, values...)
	} else {
		rows, err = r.db.pool.Query(ctx, query, values...)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the rows the upsert left: %w", err)
	}
	defer rows.Close()
	found := map[string]*types.Session{}
	for rows.Next() {
		row, err := r.scanReturned(rows, nil)
		if err != nil {
			return nil, fmt.Errorf("failed to scan result: %w", err)
		}
		if text, ok := sessionKeyOf(on, row); ok {
			found[text] = row
		}
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating results: %w", err)
	}
	out := make([]*types.Session, len(inputs))
	for i, input := range inputs {
		text, _ := sessionKeyOf(on, input)
		row := found[text]
		if row == nil {
			return nil, fmt.Errorf("the Session row that holds the key %s is deleted: %w", string(on), ErrNotFound)
		}
		out[i] = row
	}
	return out, nil
}

// heldOfKey reads the row that holds input's value of the unique key on,
// keyValues the values of the key's columns its insert binds, which an
// upsert left as it was: by rowsOfKeys, or, for a key over an expression,
// whose columns read no row, by the expression's value over keyValues
// (sqlutil.UniqueKey.Held, D105). A key no live row holds is ErrNotFound.
func (r *SessionRepository) heldOfKey(ctx context.Context, on SessionUniqueKey, keyValues []any, input *types.Session) (*types.Session, error) {
	query := sessionUniqueKeys[on].held
	if query == "" {
		found, err := r.rowsOfKeys(ctx, on, [][]any{keyValues}, []*types.Session{input})
		if err != nil {
			return nil, err
		}
		return found[0], nil
	}
	var read pgx.Row
	if r.tx != nil {
		read = r.tx.QueryRow(ctx, query, keyValues...)
	} else {
		read = r.db.pool.QueryRow(ctx, query, keyValues...)
	}
	row, err := r.scanReturned(read, nil)
	if err == pgx.ErrNoRows {
		return nil, fmt.Errorf("the Session row that holds the key %s is deleted: %w", string(on), ErrNotFound)
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read the row the upsert left: %w", err)
	}
	return row, nil
}

// CreateMany inserts multiple Session rows, each a create of the behaviors'
// core (D103), in order, in one transaction.
func (r *SessionRepository) CreateMany(ctx context.Context, inputs []*SessionCreate) ([]*types.Session, error) {
	if len(inputs) == 0 {
		return []*types.Session{}, nil
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) ([]*types.Session, error) {
		repo := &SessionRepository{tx: tx, txDB: r.database()}
		rows := make([]*types.Session, 0, len(inputs))
		for _, input := range inputs {
			row, err := repo.createThroughCore(ctx, input)
			if err != nil {
				return nil, err
			}
			rows = append(rows, row)
		}
		return rows, nil
	})
}

// UpdateOne updates a single Session row by ID through the behaviors' core
// (D103), in a transaction: the own fields update sets, which holds no field
// a behavior owns, and the row is read back. The update presents the
// preconditions WithPreconditions names (D104). It returns ErrNotFound when
// no live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *SessionRepository) UpdateOne(ctx context.Context, id types.IdentityUUID, update *SessionUpdate) (*types.Session, error) {
	if update == nil {
		update = &SessionUpdate{}
	}
	return inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (*types.Session, error) {
		repo := &SessionRepository{tx: tx, txDB: r.database()}
		patch := repo.corePatch(update)
		columns, err := repo.updateColumns(ctx, update)
		if err != nil {
			return nil, err
		}
		if len(patch) == 0 && len(columns) == 0 {
			return nil, fmt.Errorf("no fields to update")
		}
		if err := rules.RunUpdate(ctx, rulesHost(tx), "Session", id.String(), patch, behaviorCaller(ctx), &rules.ExecuteOptions{OwnColumns: columns, Preconditions: behaviorPreconditions(ctx)}); err != nil {
			return nil, behaviorNotFound(err, "Session", id)
		}
		return repo.GetOne(ctx, id, nil)
	})
}

// UpdateMany updates multiple Session records matching the filter
func (r *SessionRepository) UpdateMany(ctx context.Context, filter *SessionFilter, update *SessionUpdate) (int, error) {
	// Build UPDATE query
	var setClauses []string
	var values []interface{}
	paramNum := 0
	if update.Device != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`device = $%d`, paramNum))
		values = append(values, (*update.Device).ToUUID())
	}
	if update.Agent != nil {
		paramNum++
		setClauses = append(setClauses, fmt.Sprintf(`agent = $%d`, paramNum))
		values = append(values, *update.Agent)
	}

	// Set updated_at

	// Set updated_by

	if len(setClauses) == 0 {
		return 0, fmt.Errorf("no fields to update")
	}

	// Build WHERE clause
	whereClause := filter.buildWhereClause(&values, paramNum)

	query := fmt.Sprintf(
		`UPDATE "session" SET %s%s`,
		strings.Join(setClauses, ", "),
		whereClause,
	)

	// Execute query
	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to execute update: %w", err)
	}

	return int(result.RowsAffected()), nil
}

// DeleteOne permanently deletes a single Session row by ID through the
// behaviors' core (D103), in a transaction. The delete presents the
// preconditions WithPreconditions names (D104). It returns ErrNotFound when
// no live row holds id, and any other refusal of the core's as the
// *rules.Refusal it is.
func (r *SessionRepository) DeleteOne(ctx context.Context, id types.IdentityUUID) error {
	_, err := inTransaction(ctx, r.database(), r.tx, func(tx pgx.Tx) (struct{}, error) {
		opts := &rules.ExecuteOptions{Preconditions: behaviorPreconditions(ctx)}
		if err := rules.RunDelete(ctx, rulesHost(tx), "Session", id.String(), behaviorCaller(ctx), opts); err != nil {
			return struct{}{}, behaviorNotFound(err, "Session", id)
		}
		return struct{}{}, nil
	})
	return err
}

// DeleteMany permanently deletes multiple Session records matching the filter
func (r *SessionRepository) DeleteMany(ctx context.Context, filter *SessionFilter) (int, error) {
	// Build WHERE clause
	var values []interface{}
	whereClause := filter.buildWhereClause(&values, 0)

	query := fmt.Sprintf(`DELETE FROM "session"%s`, whereClause)

	var result pgconn.CommandTag
	var err error
	if r.tx != nil {
		result, err = r.tx.Exec(ctx, query, values...)
	} else {
		result, err = r.db.pool.Exec(ctx, query, values...)
	}
	if err != nil {
		return 0, fmt.Errorf("failed to delete records: %w", err)
	}

	return int(result.RowsAffected()), nil
}
